#include <memory>
#include <string>
#include <utility>
#include <vector>

struct Folder
{
    std::string name{};
    std::vector<std::shared_ptr<Folder>> children{};
    std::weak_ptr<Folder> parent{};
};

std::shared_ptr<Folder> makeFolder(std::string name)
{
    auto folder{ std::make_shared<Folder>() };
    folder->name = std::move(name);
    return folder;
}

void addChild(const std::shared_ptr<Folder>& parent, const std::shared_ptr<Folder>& child)
{
    parent->children.push_back(child);
    child->parent = parent;
}

std::string path(const std::shared_ptr<Folder>& folder)
{
    std::string result{ folder->name };
    auto up{ folder->parent.lock() };
    while (up)
    {
        result = up->name + "/" + result;
        up = up->parent.lock();
    }
    return result;
}

unitTests:
TEST("children and parents are linked") { auto root{ makeFolder("root") }; auto docs{ makeFolder("docs") }; addChild(root, docs); CHECK_EQ(root->children.size(), 1u); CHECK(docs->parent.lock() == root); }
TEST("path") { auto root{ makeFolder("root") }; auto docs{ makeFolder("docs") }; auto notes{ makeFolder("notes") }; addChild(root, docs); addChild(docs, notes); CHECK_EQ(path(notes), "root/docs/notes"); CHECK_EQ(path(docs), "root/docs"); CHECK_EQ(path(root), "root"); }
TEST("dropping the root frees the whole tree (no cycle)") {
    std::weak_ptr<Folder> watchRoot, watchChild;
    {
        auto root{ makeFolder("root") };
        auto child{ makeFolder("child") };
        addChild(root, child);
        watchRoot = root;
        watchChild = child;
    }
    CHECK(watchRoot.expired());
    CHECK(watchChild.expired());
}
TEST("a child can outlive its parent safely") { auto child{ makeFolder("orphan") }; { auto root{ makeFolder("root") }; addChild(root, child); } CHECK(child->parent.expired()); CHECK_EQ(path(child), "orphan"); }

